// {{TITLE_KT}} — the mobile app (Android, iOS, desktop JVM), generated by stapel-create-project --mobile kmp.
// A separate Gradle build that consumes stapel-kmp by Maven coordinates only: the version catalog
// "{{GROUP}}:{{CATALOG}}:<stapel.version>", the BOM, the brick libraries and the two Gradle plugins.
//
// Where the stapel artifacts come from: `stapel.repo` in gradle.properties (or -Pstapel.repo=…):
//   central       Maven Central (released trains)
//   local         mavenLocal (`./gradlew publishToMavenLocal` in a stapel-kmp checkout)
//   <directory>   a staging repository directory (`publishAllPublicationsToStagingRepository`)
val stapelGroup = "{{GROUP}}"
val stapelVersion: String = providers.gradleProperty("stapel.version").get()
val stapelRepo: String = providers.gradleProperty("stapel.repo").getOrElse("central")

pluginManagement {
    val group = "{{GROUP}}"
    val repo = providers.gradleProperty("stapel.repo").getOrElse("central")
    repositories {
        when (repo) {
            "central" -> {}
            "local" -> mavenLocal { content { includeGroupAndSubgroups(group) } }
            else -> maven {
                name = "stapelStaging"
                url = uri(file(repo))
                content { includeGroupAndSubgroups(group) }
            }
        }
        google {
            mavenContent {
                includeGroupAndSubgroups("androidx")
                includeGroupAndSubgroups("com.android")
                includeGroupAndSubgroups("com.google")
            }
        }
        mavenCentral()
        gradlePluginPortal()
    }
}

dependencyResolutionManagement {
    repositoriesMode = RepositoriesMode.FAIL_ON_PROJECT_REPOS
    repositories {
        when (stapelRepo) {
            "central" -> {}
            "local" -> mavenLocal { content { includeGroupAndSubgroups(stapelGroup) } }
            else -> maven {
                name = "stapelStaging"
                url = uri(file(stapelRepo))
                content { includeGroupAndSubgroups(stapelGroup) }
            }
        }
        google {
            mavenContent {
                includeGroupAndSubgroups("androidx")
                includeGroupAndSubgroups("com.android")
                includeGroupAndSubgroups("com.google")
            }
        }
        mavenCentral {
            if (stapelRepo != "central") content { excludeGroupAndSubgroups(stapelGroup) }
        }
    }
    versionCatalogs {
        create("libs") { from("$stapelGroup:{{CATALOG}}:$stapelVersion") }
    }
}

rootProject.name = "{{ROOT_NAME}}"

include(":androidApp")
include(":desktopApp")
include(":shared")
